import{_ as a,C as n,o,c as i,j as e,a as r,E as h,a6 as l}from"./chunks/framework.CCKCzdWs.js";const w=JSON.parse('{"title":"Stuck tests","description":"A running test that has run far longer than its passing runs took is marked Stuck? on its run page, and a test.stuck notification goes out once per attempt, with no viewer and no live view needed.","frontmatter":{"title":"Stuck tests","description":"A running test that has run far longer than its passing runs took is marked Stuck? on its run page, and a test.stuck notification goes out once per attempt, with no viewer and no live view needed.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/stuck-tests.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/stuck-tests.html"}],["meta",{"property":"og:title","content":"Stuck tests | Piwi Dashboard"}],["meta",{"property":"og:description","content":"A running test that has run far longer than its passing runs took is marked Stuck? on its run page, and a test.stuck notification goes out once per attempt, with no viewer and no live view needed."}]]},"headers":[],"relativePath":"features/stuck-tests.md","filePath":"features/stuck-tests.md","lastUpdated":1793447101000}'),u={name:"features/stuck-tests.md"};function c(d,t,p,m,g,f){const s=n("Needs");return o(),i("div",null,[t[0]||(t[0]=e("h1",{id:"stuck-tests",tabindex:"-1"},[r("Stuck tests "),e("a",{class:"header-anchor",href:"#stuck-tests","aria-label":'Permalink to "Stuck tests"'},"​")],-1)),h(s,{reporter:""}),t[1]||(t[1]=l('<p>A CI run that never ends is often one test waiting on something that will not come: a button that stays disabled, a page that never loads, a lock never released. Piwi says so while the run is still going. A running test that has run far longer than it usually does is marked <strong>Stuck?</strong> on its run page, and a <code>test.stuck</code> notification goes to the project&#39;s channels. Nobody needs to have the run open, and the <a href="./live-view.html">live view</a> does not need to be on.</p><h2 id="when-a-test-is-stuck" tabindex="-1">When a test is stuck <a class="header-anchor" href="#when-a-test-is-stuck" aria-label="Permalink to &quot;When a test is stuck&quot;">​</a></h2><p>The dashboard checks the running tests of its live runs every 15 seconds. A test is stuck when its current attempt has run longer than both:</p><ul><li>two minutes, whatever the test usually takes;</li><li>three times its longest duration among its last ten passing executions on the same browser.</li></ul><p>A test needs two passing executions on that browser before any attempt of it can be stuck: a new test is never flagged. The executions read are the ones a baseline reads, so no Flake Lab or investigation run and no environment incident. The time counts from the start the attempt&#39;s begin event names, else from when the dashboard heard it begin; the reporter&#39;s begin events name none. Each attempt is said to be stuck once; a retry is a new attempt.</p><p>The question mark is meant: a test can be slow for a good reason, a large import or a cold cache. The rule says only that this attempt is far outside what its passing runs took.</p><h2 id="on-the-run-page" tabindex="-1">On the run page <a class="header-anchor" href="#on-the-run-page" aria-label="Permalink to &quot;On the run page&quot;">​</a></h2><p>A stuck test&#39;s row on the run page&#39;s <strong>Tests</strong> tab carries a <strong>Stuck?</strong> badge, how long it has run and the longest its last passing runs took: <code>Running for 7 minutes, usually 41.2s at most</code>. The row&#39;s live step names the step it is in. With the project&#39;s <a href="./live-view.html">live view</a> on, <strong>Watch</strong> shows its page and, in a CI run, what its current call waits for. The badge leaves the row when the attempt ends.</p><p>A page opened after the test was said to be stuck shows it too: the dashboard keeps it with the running test.</p><h2 id="the-notification" tabindex="-1">The notification <a class="header-anchor" href="#the-notification" aria-label="Permalink to &quot;The notification&quot;">​</a></h2><p><code>test.stuck</code> fires once per attempt, through the channels of the project&#39;s <a href="./notifications.html#subscriptions">subscriptions</a> that chose it. Its message names the test, how long it has run against its usual time, the run with its branch and environment, the browser and worker, and the test&#39;s owner. Its button opens the run with its <strong>Tests</strong> tab searched for the test. The payload is on <a href="/reference/notification-events.html#payload-fields-by-event">Notification events &amp; webhooks</a>.</p><p>The branch, environment, owner and <strong>Default branch only</strong> filters apply to it. A run that sends no notification sends none: a run from an editor, a bisect step, a reproduction, or a partial run from a developer&#39;s machine or the desktop app.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>A live run on this dashboard.</strong> The running tests are kept in the memory of the server the run reports to, as the run&#39;s live events are. A dashboard that restarts forgets them until each test&#39;s next attempt begins, and it needs one dashboard server (<a href="/operate/deployment.html#resource-requirements">Resource requirements</a>).</li><li><strong>Fixed thresholds.</strong> Two minutes and three times the longest pass are the same for every project.</li><li><strong>No history, no verdict.</strong> A test with fewer than two passing executions on its browser is never said to be stuck.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./live-view.html">Live view of a run</a>: watch a stuck test&#39;s page and what it waits for</li><li><a href="./notifications.html">Notifications &amp; alerts</a>: channels and subscriptions</li><li><a href="/reference/notification-events.html">Notification events &amp; webhooks</a></li></ul>',16))])}const v=a(u,[["render",c]]);export{w as __pageData,v as default};
